<template>
  <main class="lab-page" v-loading="loading">
    <header class="lab-header">
      <div><p class="overline">车站与区间控制实验</p><h1>实验专题</h1><p>从进路办理到区间闭塞，读图、记录现象，再解释原因。</p></div>
      <div class="header-actions"><span class="count">{{ topics.length }} 个专题 · {{ questions.length }} 道复合题</span><button @click="showOriginal = true">查看原始站场 ↗</button></div>
    </header>
    <div class="mode-tabs"><button :class="{active:mode==='learn'}" @click="mode='learn'">专题作答</button><button :class="{active:mode==='history'}" @click="openHistory">我的作答 <span>{{ attempts.length }}</span></button><button v-if="canReview" :class="{active:mode==='review'}" @click="router.push(user.isAdmin?'/admin/grading':'/teacher/grading')">批阅中心</button></div>
    <p v-if="notice" class="notice" role="alert">{{ notice }}</p>

    <template v-if="mode==='learn'">
      <nav class="topic-grid" aria-label="实验专题">
        <button v-for="topic in topics" :key="topic.id" :class="['topic-card',{active:topic.id===topicId}]" :aria-pressed="topic.id===topicId" @click="chooseTopic(topic.id)">
          <span class="topic-num">{{ String(topic.id).padStart(2,'0') }}</span><span><strong>{{ topic.title }}</strong><small>{{ questions.filter(q=>q.topic===topic.id).length }} 道题 · {{ topic.id<=8 ? `实验 ${topic.id}` : '自主命题' }}</small></span><span class="topic-arrow">↗</span>
        </button>
      </nav>
      <section v-if="activeTopic" class="topic-intro"><div><h2>{{ activeTopic.title }}</h2><p>{{ activeTopic.objective }}</p></div><span>对应{{ activeTopic.report.replace('学号+姓名+','').replace('.doc','') }}</span></section>
      <div v-if="topicQuestions.length" class="question-tabs" aria-label="专题内题目">
        <button v-for="q in topicQuestions" :key="q.key" :class="{active:selectedKey===q.key}" :aria-pressed="selectedKey===q.key" @click="chooseQuestion(q.key)"><span>{{ String(q.sequence).padStart(2,'0') }}</span><Notation :text="q.title"/><small v-if="attempts.some(a=>a.question_id===q.id)">已提交</small></button>
      </div>
      <article v-if="question" class="workspace" :aria-busy="submitting">
        <div class="question-title"><div><span class="tag">{{ question.level }} · {{ question.kinds.join(' / ') }}</span><h2><Notation :text="question.title"/></h2></div><span class="grading-label">客观项 {{ question.automatic_max }} 分<br>教师评阅 {{ question.manual_max }} 分</span></div>
        <p class="prompt"><Notation :text="question.prompt"/></p>
        <aside v-if="question.conditions.length" class="conditions"><strong>本题条件</strong><p v-for="condition in question.conditions" :key="condition"><Notation :text="condition"/></p></aside>
        <div class="diagram-wrap"><ClassicStationCanvas :answer="emptyDiagram" :focus="focus" reference-mode @inspect="inspect"/><div class="device-readout"><span v-if="focus"><Notation :text="focus.code"/> · {{ deviceDescription }}</span><span v-else>点选设备后，在此查看名称和位置。</span></div></div>
        <section v-if="question.diagram_mode!=='station'" class="interval-context" aria-label="区间教学补充条件"><span>{{ question.diagram_mode==='semi_auto' ? '邻站' : '教学分区 A → B → C → D' }}</span><span class="interval-line">⇄</span><strong>原图本站 · {{ question.diagram_mode==='semi_auto' ? '东郊方向 / XD' : '北京方向 / X' }}</strong><small>区间部分为题设补充，站内仍以原图为准</small></section>
        <form @submit.prevent="submit" class="answer-form">
          <div class="form-caption"><h3>实验作答</h3><span>填写栏保留（反位）、[防护]、{带动}及 &lt;条件&gt;；下标显示不改变设备编号。</span></div>
          <fieldset :disabled="submitting">
            <section v-for="(field,index) in question.fields" :key="field.id" :id="`field-${field.id}`" class="answer-field">
              <div class="field-heading"><label :for="`answer-${field.id}`"><span>{{ index+1 }}</span><Notation :text="field.label"/></label><small>{{ field.kind==='essay' ? '教师评阅' : '自动核对' }} · {{ field.points }}分</small></div>
              <div v-if="field.kind==='choice'" class="choice-group" role="radiogroup" :aria-label="field.label"><label v-for="option in field.options" :key="option" :class="{selected:answers[field.id]===option}"><input type="radio" :name="field.id" :value="option" v-model="answers[field.id]"><Notation :text="option"/></label></div>
              <div v-else-if="field.kind==='multi'" class="choice-group"><label v-for="option in field.options" :key="option" :class="{selected:answers[field.id]?.includes(option)}"><input type="checkbox" :value="option" v-model="answers[field.id]"><Notation :text="option"/></label></div>
              <ol v-else-if="field.kind==='order'" class="order-list"><li v-for="(option,i) in answers[field.id]" :key="option"><span>{{ i+1 }}.</span><Notation :text="option"/><button type="button" :aria-label="`上移${option}`" :disabled="i===0" @click="move(field.id,i,-1)">↑</button><button type="button" :aria-label="`下移${option}`" :disabled="i===answers[field.id].length-1" @click="move(field.id,i,1)">↓</button></li></ol>
              <template v-else-if="field.kind==='cell'"><input :id="`answer-${field.id}`" type="text" v-model="answers[field.id]" maxlength="6000" autocomplete="off" placeholder="按原图填写设备和符号"><p v-if="answers[field.id]" class="notation-preview">记号预览：<Notation :text="answers[field.id]"/></p></template>
              <template v-else><textarea :id="`answer-${field.id}`" v-model="answers[field.id]" rows="4" maxlength="6000" placeholder="按工况逐项记录：条件 → 现象 → 原因。区分实测与推测，并写出依据。"></textarea><div class="word-count">{{ (answers[field.id]||'').length }} / 6000</div></template>
            </section>
          </fieldset>
          <div class="submit-row"><p>{{ draftMessage }}<br><small>记录与论述由教师评阅；自动核对结果不代表实验现象已得到验证。</small></p><button type="submit" class="primary-button" :disabled="submitting">{{ submitting?'正在保存…':'提交作答 →' }}</button></div>
        </form>
        <section v-if="result" class="feedback" aria-live="polite" ref="feedbackPanel"><h3>作答已保存 · {{ result.result.status==='pending_review'?'等待教师评阅':'评阅完成' }}</h3><p v-if="result.result.automatic_max">客观项 {{ result.result.automatic_score }} / {{ result.result.automatic_max }} 分<span v-if="result.result.status==='pending_review'">；论述部分尚未计分。</span></p><p v-else>本题为记录与论述题，保存成功后由教师评阅，不自动判定正确或错误。</p><div v-for="item in result.result.feedback" :key="item.id" :class="['feedback-item',item.status]"><strong>{{ item.status==='correct'?'✓':item.status==='incorrect'?'需调整':item.status==='partial'?'部分得分':'待评阅' }} · <Notation :text="item.label"/></strong><template v-if="item.status!=='pending_review'"><p v-for="error in item.errors" :key="error"><Notation :text="error"/></p><p>参考填写：<Notation :text="Array.isArray(item.expected)?item.expected.join(' → '):item.expected" :runs="item.expected_runs"/></p><p><Notation :text="item.explanation"/></p><button v-if="item.status==='incorrect'" @click="locateField(item.id)">回到本栏修改 ↑</button></template><template v-else><p>{{ item.message }}</p><p v-if="item.explanation" class="manual-reference"><Notation :text="item.explanation"/></p><ul><li v-for="point in item.criteria" :key="point">{{ point }}</li></ul></template></div></section>
        <details class="source-note"><summary>实验报告对应位置</summary><p>{{ question.topic_info.report }} · {{ question.source_section }}</p><p>原有实验专题以四份报告为依据；管理员新增或修订题目按本题标注的命题依据与评分规则评阅，站内设备采用原始图。</p></details>
      </article>
      <el-empty v-if="!loading&&!questions.length" description="专题尚未导入"/>
    </template>

    <section v-else-if="mode==='history'" class="records"><div class="records-heading"><h2>我的专题作答</h2><button @click="openHistory">刷新评阅状态</button></div><el-empty v-if="!attempts.length" description="还没有提交专题作答"/><article v-for="attempt in attempts" :key="attempt.id" class="record"><header><strong><Notation :text="attempt.question_title"/></strong><span>{{ attempt.result.status==='graded'?'已评阅':'待教师评阅' }}</span></header><small>{{ timeText(attempt.created_at) }}</small><p>客观项 {{ attempt.result.automatic_score }}/{{ attempt.result.automatic_max }}<template v-if="attempt.result.total_score!==null"> · 总分 {{ attempt.result.total_score }}/{{ attempt.result.total_max }}</template><template v-else> · 论述未计分</template></p><details><summary>查看提交内容与反馈</summary><div v-for="field in attempt.result.feedback" :key="field.id" class="history-field"><strong><Notation :text="field.label"/></strong><p><Notation :text="answerText(attempt.answers[field.id])"/></p><template v-if="field.status!=='pending_review'"><p>{{ field.status==='correct'?'核对正确':field.status==='partial'?'部分得分':'需调整' }} · {{ field.points }}/{{ field.max_points }} 分</p><p v-for="error in field.errors" :key="error"><Notation :text="error"/></p><p>参考填写：<Notation :text="answerText(field.expected)" :runs="field.expected_runs"/></p><p class="muted"><Notation :text="field.explanation"/></p></template><p v-if="field.status==='pending_review'&&field.explanation" class="manual-reference"><Notation :text="field.explanation"/></p><p v-if="attempt.review?.field_comments?.[field.id]">本栏反馈：{{ attempt.review.field_comments[field.id] }}</p><p v-if="attempt.review?.scores[field.id]!==undefined">教师评分：{{ attempt.review.scores[field.id] }}/{{ field.max_points }}</p></div></details><p v-if="attempt.review" class="teacher-comment">教师评语：{{ attempt.review.comment }}</p></article></section>

    <section v-else class="records"><div class="records-heading"><h2>专题作答评阅</h2><button @click="openReviews">刷新</button></div><el-empty v-if="!reviews.length" description="暂无学生专题作答"/><article v-for="attempt in reviews" :key="attempt.id" class="record"><header><strong>{{ attempt.student_name }} · <Notation :text="attempt.question_title"/></strong><span>{{ attempt.review?'已评阅':'待评阅' }}</span></header><p class="muted">{{ attempt.report }} · {{ attempt.source_section }}</p><p>客观项 {{ attempt.result.automatic_score }}/{{ attempt.result.automatic_max }}</p><details :open="!attempt.review"><summary>展开作答与评分要点</summary><div v-for="field in attempt.result.feedback" :key="field.id" class="history-field"><strong><Notation :text="field.label"/></strong><p><Notation :text="answerText(attempt.answers[field.id])"/></p><template v-if="field.status==='pending_review'"><ul><li v-for="criterion in field.criteria" :key="criterion">{{ criterion }}</li></ul><label>教师评分 <input type="number" :aria-label="`作答${attempt.id}-${field.label}-评分`" min="0" :max="field.max_points" step="1" :disabled="Boolean(attempt.review)||reviewBusy===attempt.id" v-model.number="marks[attempt.id].scores[field.id]"> / {{ field.max_points }}</label></template><p v-else><Notation :text="field.explanation"/></p></div><label :for="`comment-${attempt.id}`">教师评语</label><textarea :id="`comment-${attempt.id}`" rows="3" maxlength="6000" :disabled="Boolean(attempt.review)||reviewBusy===attempt.id" v-model="marks[attempt.id].comment"></textarea><button v-if="!attempt.review" class="primary-button" :disabled="reviewBusy===attempt.id" @click="mark(attempt)">{{ reviewBusy===attempt.id?'保存中…':'保存评阅' }}</button><p v-else>总分 {{ attempt.result.total_score }}/{{ attempt.result.total_max }}</p></details></article></section>

    <el-dialog v-model="showOriginal" title="原始站场图 · 圈定范围" width="94%" top="3vh"><svg viewBox="0 0 1706 1279" class="original-photo" role="img" aria-label="原始图横向展示"><image :href="originalUrl" width="1279" height="1706" transform="translate(0 1279) rotate(-90)"/></svg></el-dialog>
  </main>
</template>

<script setup>
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useUserStore } from '@/store/user'
import ClassicStationCanvas from '@/components/ClassicExam/ClassicStationCanvas.vue'
import Notation from '@/components/RailwayNotation.vue'
import { topology } from '@/domain/classicStation'
import { getLabQuestions,getLabQuestion,getLabAttempts,getLabReviews,submitLabAnswer,reviewLabAttempt } from '@/api/labTopics'
import originalUrl from '../../../../../pictures/原始图.jpg?url'

const route=useRoute(),router=useRouter(),user=useUserStore()
const questions=ref([]),question=ref(null),attempts=ref([]),reviews=ref([]),marks=ref({}),answers=ref({})
const topicId=ref(1),selectedKey=ref(''),mode=ref('learn'),loading=ref(false),submitting=ref(false),reviewBusy=ref(null),notice=ref(''),result=ref(null),focus=ref(null),showOriginal=ref(false),feedbackPanel=ref(null),draftMessage=ref('草稿保存在本机，提交后保存到项目数据库。')
const emptyDiagram={route_buttons:[],switches:{},hostile_signals:[],track_sections:[]}
const canReview=computed(()=>['teacher','admin'].includes(user.role))
const topics=computed(()=>[...new Map(questions.value.map(q=>[q.topic,q.topic_info])).values()])
const activeTopic=computed(()=>topics.value.find(t=>t.id===topicId.value))
const topicQuestions=computed(()=>questions.value.filter(q=>q.topic===topicId.value))
const deviceDescription=computed(()=>{
  const s=topology.signals.find(s=>s.name===focus.value?.code)
  if(s)return `${s.type}信号机 · ${s.track}股道`
  const w=topology.switches.find(w=>w.id===focus.value?.code)
  if(w)return `${w.type} · 连接${w.connects.join('与')}股道`
  const section=topology.sections.find(s=>s.name===focus.value?.code)
  return section?`轨道区段 · ${section.track}股道`:'原图参考设备'
})
let requestId=0, revision=0, initializing=false
function draftKey(q=question.value){return `srtp_lab_${user.user?.id}_${q?.key}_${q?.fingerprint}`}
function inspect(kind,code){focus.value={kind,code}}
function answerText(value){return Array.isArray(value)?value.join(' → '):String(value??'')}
function timeText(value){return new Date(value+'Z').toLocaleString('zh-CN')}
function saveDraft(){if(!question.value||initializing)return;try{localStorage.setItem(draftKey(),JSON.stringify(answers.value));draftMessage.value='草稿已保存到本机。'}catch{draftMessage.value='本机草稿保存失败，请及时提交。'}}
watch(answers,()=>{if(initializing)return;revision++;result.value=null;saveDraft()},{deep:true,flush:'sync'})
function chooseTopic(id){if(submitting.value)return;topicId.value=id;const q=questions.value.find(q=>q.topic===id);if(q)chooseQuestion(q.key)}
async function chooseQuestion(key,updateUrl=true){
  if(submitting.value)return
  saveDraft(); const current=++requestId; loading.value=true;notice.value='';result.value=null;focus.value=null;question.value=null
  try{const q=await getLabQuestion(key);if(current!==requestId)return
    initializing=true;question.value=q;selectedKey.value=key;topicId.value=q.topic
    let draft=null;try{draft=JSON.parse(localStorage.getItem(draftKey(q)))}catch{}
    answers.value=Object.fromEntries(q.fields.map(f=>[f.id,draft?.[f.id]??(f.kind==='multi'?[]:f.kind==='order'?[...f.options]:'')]))
    initializing=false;revision++;draftMessage.value=draft?'已恢复本题草稿。':'草稿保存在本机，提交后保存到项目数据库。'
    if(updateUrl)router.replace({query:{q:key}})
  }catch(e){if(current===requestId)notice.value=message(e,'题目加载失败，可刷新重试。')}
  finally{if(current===requestId)loading.value=false;initializing=false}
}
function move(id,index,offset){const values=[...answers.value[id]];[values[index],values[index+offset]]=[values[index+offset],values[index]];answers.value[id]=values}
function message(e,fallback){const detail=e.response?.data?.detail;return typeof detail==='string'?detail:fallback}
async function submit(){
  if(!question.value||submitting.value)return
  const missing=question.value.fields.find(f=>Array.isArray(answers.value[f.id])?!answers.value[f.id].length:!String(answers.value[f.id]??'').trim())
  if(missing){notice.value='请完成全部答题栏后提交。';locateField(missing.id);return}
  const q=question.value,snapshot=JSON.parse(JSON.stringify(answers.value)),rev=revision
  submitting.value=true;notice.value=''
  try{const response=await submitLabAnswer(q.key,{fingerprint:q.fingerprint,answers:snapshot});attempts.value.unshift(response)
    if(rev===revision&&question.value?.key===q.key){result.value=response;await nextTick();feedbackPanel.value?.scrollIntoView({behavior:'smooth',block:'start'})}
  }catch(e){notice.value=message(e,'提交失败，答案已保留，可重试。')}
  finally{submitting.value=false}
}
function locateField(id){document.getElementById(`field-${id}`)?.scrollIntoView({behavior:'smooth',block:'center'});document.getElementById(`answer-${id}`)?.focus({preventScroll:true})}
async function openHistory(){mode.value='history';notice.value='';try{attempts.value=await getLabAttempts()}catch(e){notice.value=message(e,'作答记录加载失败。')}}
async function openReviews(){mode.value='review';notice.value='';try{reviews.value=await getLabReviews();marks.value=Object.fromEntries(reviews.value.map(a=>[a.id,a.review?JSON.parse(JSON.stringify(a.review)):{scores:Object.fromEntries(a.rubric.map(f=>[f.id,''])),comment:''}]))}catch(e){notice.value=message(e,'评阅记录加载失败。')}}
async function mark(attempt){
  const value=marks.value[attempt.id]
  if(!value.comment.trim()||attempt.rubric.some(f=>!Number.isInteger(value.scores[f.id])||value.scores[f.id]<0||value.scores[f.id]>f.points)){notice.value='请逐栏填写有效评分及评语。';return}
  reviewBusy.value=attempt.id;notice.value=''
  try{const updated=await reviewLabAttempt(attempt.id,value);Object.assign(attempt,updated)}catch(e){notice.value=message(e,'评阅保存失败。')}finally{reviewBusy.value=null}
}
watch(()=>route.query.q,key=>{if(typeof key==='string'&&key!==selectedKey.value&&!submitting.value&&questions.value.some(q=>q.key===key))chooseQuestion(key,false)})
onMounted(async()=>{loading.value=true;try{const data=await Promise.all([getLabQuestions(),getLabAttempts()]);questions.value=data[0];attempts.value=data[1];const key=questions.value.find(q=>q.key===route.query.q)?.key||questions.value[0]?.key;if(key)await chooseQuestion(key)}catch(e){notice.value=message(e,'专题加载失败，可刷新重试。')}finally{loading.value=false}})
</script>

<style scoped>
.manual-reference{white-space:pre-line;overflow-wrap:anywhere;line-height:1.9}
.lab-page{max-width:1550px;margin:auto;color:#19334d}.lab-header{display:flex;justify-content:space-between;gap:24px;align-items:center;margin-bottom:22px}.overline{color:#337796;font-size:var(--ui-text-meta);letter-spacing:2px;margin:0 0 8px}.lab-header h1{font-size:32px;margin:0 0 10px}.lab-header p:last-child{margin:0;color:#738497;line-height:1.8}.header-actions{display:flex;flex-direction:column;align-items:flex-end;gap:12px}.count{font-size:var(--ui-text-base);color:#52728a}button{font:inherit;border:1px solid #dce6ee;border-radius:6px;padding:8px 12px;background:white;color:#42677e;cursor:pointer}button:disabled{opacity:.5;cursor:default}.mode-tabs{display:flex;gap:8px;border-bottom:1px solid #dfe7ee;margin-bottom:22px;padding-bottom:10px}.mode-tabs button{border:none;background:transparent}.mode-tabs button.active{color:#006fa9;background:#e6f2fa}.mode-tabs span{font-size:var(--ui-text-meta);margin-left:6px}.topic-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.topic-card{display:flex;align-items:center;gap:12px;text-align:left;padding:17px 13px;min-height:88px}.topic-card.active{background:#edf6fc;border-color:#54a0c7;box-shadow:inset 3px 0 #0075b7}.topic-num{font:27px Georgia;color:#586f82}.topic-card strong{display:block;font-weight:600;font-size:var(--ui-text-base);line-height:1.6}.topic-card small{display:block;font-size:var(--ui-text-sm);color:#586f82;margin-top:7px}.topic-arrow{margin-left:auto;color:#586f82}.topic-intro{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:26px 0 18px}.topic-intro h2{font-size:var(--ui-text-heading);margin:0 0 8px}.topic-intro p{font-size:var(--ui-text-base);color:#738497;line-height:1.8;margin:0}.topic-intro>span{font-size:var(--ui-text-meta);white-space:nowrap;color:#586f82}.question-tabs{display:flex;gap:10px;margin-bottom:18px}.question-tabs button{flex:1;text-align:left;display:flex;align-items:center;gap:10px;padding:12px}.question-tabs button>span:first-child{c